/**
 * A SQLite file written by the Node runtime stack (`@ixo/sqlite-saver` on
 * `better-sqlite3` + the Node `sessions` DDL). Generated by
 * `generate-legacy-db.mjs` — do not edit by hand; re-run the generator.
 *
 * Contents: thread 'legacy-thread-1' with two checkpoints (ids
 * 1f1a0b09-7edd-6330-8000-5c7ef1c05fc0 and 1f1a0b09-7eff-6611-8001-4deb24fb0007), one human + one AI message, one
 * pending write on the first checkpoint, one TASKS write on the second, and a
 * sessions row 'legacy-thread-1' in room '!legacyroom:devmx.ixo.earth'.
 */
export const LEGACY_THREAD_ID = 'legacy-thread-1';
export const LEGACY_SESSION_ID = 'legacy-thread-1';
export const LEGACY_ROOM_ID = '!legacyroom:devmx.ixo.earth';
export const LEGACY_CHECKPOINT_IDS = [
  '1f1a0b09-7edd-6330-8000-5c7ef1c05fc0',
  '1f1a0b09-7eff-6611-8001-4deb24fb0007',
] as const;
export const LEGACY_DB_BYTE_LENGTH = 77824;
export const LEGACY_DB_BASE64 =
  '';

export function legacyDbBytes(): Uint8Array {
  const binary = atob(LEGACY_DB_BASE64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes;
}
